'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { dataHub } from '@/lib/dataIntegration';
import { 
  Users, Calendar, Clock, AlertTriangle, Shield, TrendingUp, 
  CheckCircle, XCircle, Activity, BarChart3, Bell, ArrowRight 
} from 'lucide-react';

export default function UnifiedDashboard() {
  const dashboardData = dataHub.getDashboardData();
  const notifications = dataHub.getNotifications();
  const [userTier, setUserTier] = useState('PROFESSIONAL');

  useEffect(() => {
    const tier = localStorage.getItem('tier') || 'PROFESSIONAL';
    setUserTier(tier);
  }, []);

  return (
    <div className="min-h-screen bg-transparent p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div>
            <h1 className="text-5xl font-bold text-white mb-2 drop-shadow-lg">Command Center</h1>
            <p className="text-lg text-purple-300">Real-time business intelligence and operations hub</p>
          </div>
        </div>

        {/* Notifications Banner */}
        {notifications.length > 0 && (
          <div className="mb-6 bg-yellow-500/20 backdrop-blur-xl border-l-4 border-yellow-400 p-4 rounded-lg">
            <div className="flex items-center gap-3 mb-2">
              <Bell className="w-5 h-5 text-yellow-300" />
              <h2 className="font-bold text-yellow-100">{notifications.length} Active Notifications</h2>
            </div>
            <div className="space-y-2">
              {notifications.map(notif => (
                <div key={notif.id} className="flex items-start justify-between">
                  <div>
                    <p className="font-medium text-yellow-100">{notif.title}</p>
                    <p className="text-sm text-yellow-200">{notif.message}</p>
                  </div>
                  {notif.link && (
                    <Link href={notif.link} className="text-blue-300 hover:text-blue-200 font-medium text-sm flex items-center gap-1">
                      View <ArrowRight className="w-4 h-4" />
                    </Link>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Main Metrics Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          {/* Employees */}
          <Link href="/employees" className="block">
            <div className="bg-white/10 backdrop-blur-xl p-6 rounded-xl shadow-lg border-2 border-white/20 hover:border-blue-400 transition-all cursor-pointer group">
              <div className="flex items-center justify-between mb-4">
                <div className="p-3 bg-blue-500/20 rounded-lg group-hover:bg-blue-500/30 transition-colors">
                  <Users className="w-6 h-6 text-blue-300" />
                </div>
                <button className="text-xs text-purple-200 hover:text-white px-2 py-1 rounded bg-white/5 hover:bg-white/10 transition-colors">
                  ⚙️
                </button>
              </div>
              <h3 className="text-3xl font-bold text-white mb-1">{dashboardData.employees.active}</h3>
              <p className="text-purple-100 font-semibold">Active Employees</p>
              <p className="text-sm text-purple-200 mt-2">Avg Performance: {dashboardData.employees.avgPerformance.toFixed(1)}%</p>
              <p className="text-xs text-purple-300 mt-1">{dashboardData.employees.total - dashboardData.employees.active} on leave</p>
            </div>
          </Link>

          {/* Scheduling */}
          <Link href="/calendar" className="block">
            <div className="bg-white/10 backdrop-blur-xl p-6 rounded-xl shadow-lg border-2 border-white/20 hover:border-green-400 transition-all cursor-pointer group">
              <div className="flex items-center justify-between mb-4">
                <div className="p-3 bg-green-500/20 rounded-lg group-hover:bg-green-500/30 transition-colors">
                  <Calendar className="w-6 h-6 text-green-300" />
                </div>
                <button className="text-xs text-purple-200 hover:text-white px-2 py-1 rounded bg-white/5 hover:bg-white/10 transition-colors">
                  ⚙️
                </button>
              </div>
              <h3 className="text-3xl font-bold text-white mb-1">{dashboardData.shifts.upcoming}</h3>
              <p className="text-purple-100 font-semibold">Upcoming Shifts</p>
              <p className="text-sm text-purple-200 mt-2">Coverage: {((dashboardData.shifts.filled / dashboardData.shifts.total) * 100).toFixed(0)}%</p>
              <p className="text-xs text-purple-300 mt-1">{dashboardData.shifts.total - dashboardData.shifts.filled} open shifts</p>
            </div>
          </Link>

          {/* Time Off */}
          <Link href="/time-off" className="block">
            <div className="bg-white/10 backdrop-blur-xl p-6 rounded-xl shadow-lg border-2 border-white/20 hover:border-purple-400 transition-all cursor-pointer group">
              <div className="flex items-center justify-between mb-4">
                <div className="p-3 bg-purple-500/20 rounded-lg group-hover:bg-purple-500/30 transition-colors">
                  <Clock className="w-6 h-6 text-purple-300" />
                </div>
                <button className="text-xs text-purple-200 hover:text-white px-2 py-1 rounded bg-white/5 hover:bg-white/10 transition-colors">
                  ⚙️
                </button>
              </div>
              <h3 className="text-3xl font-bold text-white mb-1">{dashboardData.timeOff.pending}</h3>
              <p className="text-purple-100 font-semibold">Pending Requests</p>
              <p className="text-sm text-purple-200 mt-2">{dashboardData.timeOff.approved} approved this month</p>
              <p className="text-xs text-purple-300 mt-1">{dashboardData.timeOff.denied || 2} denied</p>
            </div>
          </Link>

          {/* Quality & Safety */}
          <Link href="/qapi" className="block">
            <div className="bg-white/10 backdrop-blur-xl p-6 rounded-xl shadow-lg border-2 border-white/20 hover:border-red-400 transition-all cursor-pointer group">
              <div className="flex items-center justify-between mb-4">
                <div className="p-3 bg-red-500/20 rounded-lg group-hover:bg-red-500/30 transition-colors">
                  <AlertTriangle className="w-6 h-6 text-red-300" />
                </div>
                <button className="text-xs text-purple-200 hover:text-white px-2 py-1 rounded bg-white/5 hover:bg-white/10 transition-colors">
                  ⚙️
                </button>
              </div>
              <h3 className="text-3xl font-bold text-white mb-1">{dashboardData.quality.openIncidents}</h3>
              <p className="text-purple-100 font-semibold">Open Incidents</p>
              <p className="text-sm text-purple-200 mt-2">{dashboardData.quality.totalIncidents} total incidents</p>
              <p className="text-xs text-purple-300 mt-1">{dashboardData.quality.resolved || 45} resolved</p>
            </div>
          </Link>
        </div>

        {/* System Status Grid */}
        <div className="bg-white/10 backdrop-blur-xl p-6 rounded-xl shadow-lg border border-white/20 mb-8">
          <h2 className="text-xl font-bold text-white mb-4">System Integration Status</h2>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {[
              { name: 'HR Analytics', status: 'Connected', link: '/hr/analytics' },
              { name: 'Scheduling', status: 'Connected', link: '/calendar' },
              { name: 'Time & Attendance', status: 'Connected', link: '/attendance' },
              { name: 'QAPI Portal', status: 'Connected', link: '/qapi' },
              { name: 'Reports Dashboard', status: 'Connected', link: '/reports' },
              { name: 'Policy Center', status: 'Connected', link: '/settings/policies' },
              { name: 'Compliance', status: 'Connected', link: '/compliance' },
              { name: 'Learning Hub', status: 'Connected', link: '/learning' },
            ].map((system) => (
              <Link key={system.name} href={system.link}>
                <div className="p-4 bg-white/5 backdrop-blur-sm border border-white/20 rounded-lg hover:border-blue-400 hover:shadow-lg transition-all cursor-pointer">
                  <div className="flex items-center gap-2 mb-2">
                    <CheckCircle className="w-4 h-4 text-green-400" />
                    <span className="text-xs font-medium text-green-300">{system.status}</span>
                  </div>
                  <p className="text-sm font-semibold text-white">{system.name}</p>
                </div>
              </Link>
            ))}
          </div>
        </div>

        {/* Cross-System Insights */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
          {/* Department Performance */}
          <div className="bg-white/10 backdrop-blur-xl p-6 rounded-xl shadow-lg border border-white/20">
            <h2 className="text-xl font-bold text-white mb-4">Department Performance</h2>
            <div className="space-y-3">
              {['Emergency', 'ICU', 'Nursing', 'Radiology', 'Laboratory'].map((dept) => {
                const metrics = dataHub.calculateDepartmentMetrics(dept);
                const score = ((metrics.completedShifts / metrics.totalShifts) * 100) || 95;
                
                return (
                  <div key={dept}>
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-sm font-medium text-purple-100">{dept}</span>
                      <span className="text-sm font-bold text-white">{score.toFixed(0)}%</span>
                    </div>
                    <div className="w-full h-3 bg-white/10 rounded-full overflow-hidden">
                      <div 
                        className={`h-full ${score >= 90 ? 'bg-green-500' : score >= 75 ? 'bg-yellow-500' : 'bg-red-500'}`}
                        style={{ width: `${score}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Quick Actions */}
          <div className="bg-white/10 backdrop-blur-xl p-6 rounded-xl shadow-lg border border-white/20">
            <h2 className="text-xl font-bold text-white mb-4">Quick Actions</h2>
            <div className="space-y-3">
              <Link href="/qapi?tab=reports" className="block p-4 bg-white/5 backdrop-blur-sm rounded-lg hover:bg-white/10 border border-white/10 hover:border-blue-400 transition-all">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <BarChart3 className="w-5 h-5 text-blue-300" />
                    <div>
                      <p className="font-semibold text-white">Generate Executive Report</p>
                      <p className="text-sm text-purple-200">Pull data from all systems</p>
                    </div>
                  </div>
                  <ArrowRight className="w-5 h-5 text-purple-300" />
                </div>
              </Link>

              <Link href="/time-off" className="block p-4 bg-white/5 backdrop-blur-sm rounded-lg hover:bg-white/10 border border-white/10 hover:border-purple-400 transition-all">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <Clock className="w-5 h-5 text-purple-300" />
                    <div>
                      <p className="font-semibold text-white">Review Time Off Requests</p>
                      <p className="text-sm text-purple-200">{dashboardData.timeOff.pending} pending approval</p>
                    </div>
                  </div>
                  <ArrowRight className="w-5 h-5 text-purple-300" />
                </div>
              </Link>

              <Link href="/qapi?tab=incidents" className="block p-4 bg-white/5 backdrop-blur-sm rounded-lg hover:bg-white/10 border border-white/10 hover:border-red-400 transition-all">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <AlertTriangle className="w-5 h-5 text-red-300" />
                    <div>
                      <p className="font-semibold text-white">Review Open Incidents</p>
                      <p className="text-sm text-purple-200">{dashboardData.quality.openIncidents} requiring attention</p>
                    </div>
                  </div>
                  <ArrowRight className="w-5 h-5 text-purple-300" />
                </div>
              </Link>

              <Link href="/compliance" className="block p-4 bg-white/5 backdrop-blur-sm rounded-lg hover:bg-white/10 border border-white/10 hover:border-green-400 transition-all">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <CheckCircle className="w-5 h-5 text-green-300" />
                    <div>
                      <p className="font-semibold text-white">Compliance Dashboard</p>
                      <p className="text-sm text-purple-200">{dashboardData.compliance.complianceRate}% current</p>
                    </div>
                  </div>
                  <ArrowRight className="w-5 h-5 text-purple-300" />
                </div>
              </Link>
            </div>
          </div>
        </div>

        {/* Data Flow Diagram */}
        <div className="bg-white/10 backdrop-blur-xl p-6 rounded-xl shadow-lg border border-white/20">
          <h2 className="text-xl font-bold text-white mb-4">Data Integration Flow</h2>
          <p className="text-purple-200 mb-6">All systems share data through a central integration hub, ensuring consistency and real-time updates across the platform.</p>
          
          <div className="flex flex-wrap items-center justify-center gap-4">
            <div className="flex flex-col items-center">
              <div className="p-4 bg-blue-500/20 backdrop-blur-sm rounded-lg border border-blue-400/30">
                <Users className="w-6 h-6 text-blue-300" />
              </div>
              <p className="text-xs font-medium text-purple-100 mt-2">HR System</p>
            </div>

            <ArrowRight className="w-6 h-6 text-gray-400" />

            <div className="flex flex-col items-center">
              <div className="p-4 bg-green-100 rounded-lg">
                <Calendar className="w-6 h-6 text-green-600" />
              </div>
              <p className="text-xs font-medium text-gray-700 mt-2">Scheduling</p>
            </div>

            <ArrowRight className="w-6 h-6 text-gray-400" />

            <div className="flex flex-col items-center">
              <div className="p-6 bg-gradient-to-br from-purple-100 to-blue-100 rounded-lg border-2 border-purple-400">
                <Activity className="w-8 h-8 text-purple-600" />
              </div>
              <p className="text-sm font-bold text-purple-900 mt-2">Data Hub</p>
            </div>

            <ArrowRight className="w-6 h-6 text-gray-400" />

            <div className="flex flex-col items-center">
              <div className="p-4 bg-red-100 rounded-lg">
                <Shield className="w-6 h-6 text-red-600" />
              </div>
              <p className="text-xs font-medium text-gray-700 mt-2">QAPI</p>
            </div>

            <ArrowRight className="w-6 h-6 text-gray-400" />

            <div className="flex flex-col items-center">
              <div className="p-4 bg-yellow-100 rounded-lg">
                <BarChart3 className="w-6 h-6 text-yellow-600" />
              </div>
              <p className="text-xs font-medium text-gray-700 mt-2">Reports</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
